# The logo image moves off the Brand row into its own table: queries that
# join a brand (every order list) were downloading the image every time.

import django.db.models.deletion
from django.db import migrations, models


def move_logos(apps, schema_editor):
    Brand = apps.get_model("core", "Brand")
    BrandLogo = apps.get_model("core", "BrandLogo")
    for brand in Brand.objects.filter(logo_data__isnull=False):
        BrandLogo.objects.update_or_create(
            brand=brand,
            defaults={
                "data": brand.logo_data,
                "content_type": brand.logo_content_type or "application/octet-stream",
            },
        )


